// Valida Authorization: Bearer <SYNC_SECRET>. Sale con { url } o throw.
const auth = $input.first().json.headers?.authorization || '';
const secret = $env.SYNC_SECRET || '';
if (!secret) throw new Error('SYNC_SECRET not configured');
if (!auth.startsWith('Bearer ') || auth.slice(7) !== secret) {
  throw new Error('Unauthorized');
}
const url = (($input.first().json.body || {}).url || '').toString().trim();
if (!url) throw new Error('Missing url');
return [{ json: { url } }];

const urlOrId = String($input.item.json.url || '').trim();
let id = '';
if (/^\d+$/.test(urlOrId)) {
  id = urlOrId;
} else {
  const match = urlOrId.match(/models\/(\d+)/);
  if (!match) throw new Error('Entrada no vǭlida. Pon ID o URL.');
  id = match[1];
}
return { json: { externalId: id } };

const htmlStr = $input.item.json?.solution?.response || "";
const match = htmlStr.match(/<body[^>]*>(.*?)<\/body>/is);
let rawJson = match ? match[1] : htmlStr;
try {
    rawJson = rawJson.replace(/^<pre[^>]*>/i, '').replace(/<\/pre>$/i, '').trim();
    const data = JSON.parse(rawJson);
    const instances = data.instances || [];
    if (!instances.length) throw new Error('No instances found.');
    const profiles = instances.map(ins => {
      const plates = ((ins.extention || {}).modelInfo || {}).plates || [];
      const platesGrams = plates.reduce((s, p) => s + (Number(p.weight) || 0), 0);
      const platesSeconds = plates.reduce((s, p) => s + (Number(p.prediction) || 0), 0);
      const grams = Number(ins.weight) || platesGrams;
      const seconds = Number(ins.prediction) || platesSeconds;
      return {
        id: String(ins.id || ins.profileId || ''),
        title: ins.title || ins.titleTranslated || 'Perfil sin nombre',
        name: ins.name || '',
        grams: Number.isFinite(grams) ? Number(grams.toFixed(2)) : 0,
        hours: Number.isFinite(seconds) ? Number((seconds / 3600).toFixed(3)) : 0,
        plateCount: plates.length || 1,
        isDefault: !!ins.isDefault,
        needAms: !!ins.needAms,
        colorCount: Number(ins.materialColorCnt) || Number(ins.materialCnt) || 1,
        cover: ins.cover || null,
      };
    }).filter(p => p.grams > 0 || p.hours > 0);
    if (!profiles.length) throw new Error('No stats.');
    return { json: { profiles } };
} catch (e) {
    throw new Error("Parse error: " + e.message);
}
